public inherited sharing class LogPurgeJob implements Schedulable {

    // Retention windows in days.
    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext ctx) {
        purge();
    }

    @TestVisible
    private static void purge() {
        Datetime standardCutoff = Datetime.now().addDays(-STANDARD_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        // Records older than 30 days that are not retained ERROR logs:
        // any Level__c other than 'ERROR' (including blank) created before the 30-day cutoff.
        List<FB_Integration_Log__c> toDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :standardCutoff
              AND (Level__c != 'ERROR' OR Level__c = null)
        ];

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // ERROR logs are kept longer: delete only those older than 180 days.
        List<FB_Integration_Log__c> errorsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE Level__c = 'ERROR'
              AND CreatedDate < :errorCutoff
        ];

        if (!errorsToDelete.isEmpty()) {
            delete errorsToDelete;
        }
    }

    public static Id scheduleNightly() {
        LogPurgeJob job = new LogPurgeJob();
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', job);
    }
}
