public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public Opportunities(List<Opportunity> records, Boolean applyDefaults)
    {
        super(records, applyDefaults);
    }

    public override void onValidate()
    {
        validateAmountNotNegative((List<Opportunity>) Records);
        validateAmountNotChangedOnWon((List<Opportunity>) Records);
    }

    // Rule 1: on insert and update, Amount must not be negative.
    private void validateAmountNotNegative(List<Opportunity> records)
    {
        for (Opportunity record : records)
        {
            if (record.Amount != null && record.Amount < 0)
            {
                error('Amount cannot be negative.', record, Opportunity.Amount);
            }
        }
    }

    // Rule 2: on update, an opportunity that was already Closed Won before the
    // update cannot have its Amount changed. Closing as won and changing the
    // amount in the same update is allowed.
    private void validateAmountNotChangedOnWon(List<Opportunity> records)
    {
        if (!Trigger.isUpdate)
        {
            return;
        }

        Map<Id, Opportunity> originals = (Map<Id, Opportunity>) getOriginalMap();

        for (Opportunity record : records)
        {
            Opportunity original = originals.get(record.Id);

            if (original == null || original.StageName != 'Closed Won')
            {
                continue;
            }

            // Closing as won now, with the amount changed in the same update, is allowed.
            if (record.StageName != 'Closed Won')
            {
                continue;
            }

            if (record.Amount != original.Amount)
            {
                error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
            }
        }
    }
}
