public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        // Run every query in user mode so the platform enforces object, field and sharing access
        super(false, false, fflib_SObjectSelector.SOQL_ORDER_BY_DEFAULT, fflib_SObjectSelector.SOQL_ORDER_BY_DEFAULT, fflib_SObjectSelector.USER_MODE);
    }

