public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        List<Opportunity> toClose = new List<Opportunity>();
        List<Deal_Won__e> events = new List<Deal_Won__e>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName == 'Closed Won') {
                continue;
            }
            toClose.add(new Opportunity(
                Id = opp.Id,
                StageName = 'Closed Won',
                CloseDate = Date.today()
            ));
            events.add(new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            ));
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork unitOfwork = Application.UnitOfWork.newInstance();

        for (Opportunity opp : toClose) {
            unitOfwork.registerDirty(opp);
        }
        unitOfwork.registerEvent(events);

        // One commit: the opportunities are updated and, only if that succeeds,
        // the Deal_Won__e events are published by the unit of work.
        unitOfwork.commitWork();

        return toClose.size();
    }
}
