/**
 * NPSP TDTM trigger handler for Opportunity (AfterInsert, AfterUpdate).
 * Creates a single follow-up Task when an Opportunity becomes Closed Won
 * with Amount >= 5000 (or is inserted already in that state).
 *
 * Registered by the admin via NPSP Settings > Trigger Configuration:
 *   Class = OPP_MajorGiftFollowUp_TDTM, Object = Opportunity,
 *   Trigger Action = AfterInsert;AfterUpdate, Load Order = 5.
 * Deactivating that Trigger Handler record stops this handler, since it is
 * only ever invoked by NPSP's TDTM dispatcher (no Apex trigger of our own).
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        if (newlist == null || newlist.isEmpty()) {
            return null;
        }

        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject o : oldlist) {
                oldMap.put(o.Id, (Opportunity) o);
            }
        }

        List<Opportunity> qualifying = new List<Opportunity>();

        for (Opportunity opp : (List<Opportunity>) newlist) {
            Boolean nowQualified = isQualified(opp);
            if (!nowQualified) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.afterUpdate) {
                Opportunity oldOpp = oldMap.get(opp.Id);
                // Only fire on transitions into the qualifying state; an
                // already-qualified gift being edited must not create a new Task.
                if (oldOpp != null && isQualified(oldOpp)) {
                    continue;
                }
            }

            qualifying.add(opp);
        }

        if (qualifying.isEmpty()) {
            return null;
        }

        // One SOQL query: which of these opportunities already have the task?
        Set<Id> oppIds = new Set<Id>();
        for (Opportunity opp : qualifying) {
            oppIds.add(opp.Id);
        }

        Set<Id> oppsWithTask = new Set<Id>();
        for (Task t : [
            SELECT WhatId
            FROM Task
            WHERE WhatId IN :oppIds
              AND Subject = :TASK_SUBJECT
        ]) {
            oppsWithTask.add(t.WhatId);
        }

        List<Task> tasksToCreate = new List<Task>();
        for (Opportunity opp : qualifying) {
            if (oppsWithTask.contains(opp.Id)) {
                continue;
            }

            Date activityDate = null;
            if (opp.CloseDate != null) {
                activityDate = opp.CloseDate.addDays(3);
            }

            Task t = new Task(
                Subject = TASK_SUBJECT,
                Priority = 'High',
                Status = 'Not Started',
                WhatId = opp.Id,
                WhoId = opp.npsp__Primary_Contact__c,
                OwnerId = opp.OwnerId,
                ActivityDate = activityDate
            );
            tasksToCreate.add(t);
        }

        if (tasksToCreate.isEmpty()) {
            return null;
        }

        // One DML statement of our own, handed back through the TDTM wrapper.
        return new npsp.TDTM_Runnable.DmlWrapper(tasksToCreate, 'insert', false);
    }

    private static Boolean isQualified(Opportunity opp) {
        return STAGE_CLOSED_WON.equals(opp.StageName)
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }
}
