public inherited sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // Single SOQL: only the Contacts that belong to the given Accounts.
        List<Contact> contacts = [
            SELECT Id, OwnerId
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        try {
            // Bypass ALL Account trigger actions for this ownership change.
            TriggerBase.bypass(Account.SObjectType);

            List<Account> accounts = new List<Account>(accountIds.size());
            for (Id accountId : accountIds) {
                Account acc = new Account(Id = accountId);
                acc.OwnerId = newOwnerId;
                accounts.add(acc);
            }

            List<Contact> contactsToUpdate = new List<Contact>(contacts.size());
            for (Contact con : contacts) {
                Contact c = new Contact(Id = con.Id);
                c.OwnerId = newOwnerId;
                contactsToUpdate.add(c);
            }

            // All-or-none DML; exceptions propagate to the caller unchanged.
            update accounts;
            update contactsToUpdate; // Contact trigger actions run normally.
        } finally {
            // Always restore Account automation, even on exception.
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
