/**
 * Trigger Action for the Trigger Actions Framework (v0.3.4).
 * Registered on Lead, before insert: normalizes Email, Company and LeadSource.
 * Bulk-safe (200 rows), no DML, no SOQL. Field changes are written directly to
 * trigger.new records so the clean values are persisted with the original insert.
 */
public inherited sharing class TA_Lead_NormalizeContactInfo
        implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject rec : triggerNew) {
            String email = (String) rec.get(Lead.Email);
            if (email != null) {
                String trimmed = email.trim();
                // whitespace-only email becomes null rather than failing Email format validation
                rec.put(Lead.Email, String.isBlank(trimmed) ? null : trimmed.toLowerCase());
            }

            String company = (String) rec.get(Lead.Company);
            if (company != null) {
                rec.put(Lead.Company, company.trim());
            }

            if (rec.get(Lead.LeadSource) == null) {
                rec.put(Lead.LeadSource, 'Web');
            }
        }
    }
}
