/**
 * Singleton query provider for Contact before-insert trigger actions.
 *
 * The inner Service class is registered as a Trigger Action (Order 1) so that
 * the parent Account map is loaded exactly once per trigger execution and is
 * shared by all later actions. The map is reloaded on every trigger execution
 * because later DML in the same transaction can involve other accounts.
 */
public class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById;

    private TA_Contact_Queries() {
        accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action that primes the singleton before any other action runs.
     * Collects the AccountIds of all contacts in the trigger batch and loads
     * the parent accounts with a single SOQL query.
     */
    public class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (Contact c : (List<Contact>) triggerNew) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
            if (accountIds.isEmpty()) {
                TA_Contact_Queries.getInstance().accountsById = new Map<Id, Account>();
            } else {
                TA_Contact_Queries.getInstance().accountsById = new Map<Id, Account>([
                    SELECT Id, BillingStreet, BillingCity, BillingPostalCode,
                           BillingCountry, AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]);
            }
        }
    }
}
